class Solution {
    long long power(long long base, long long exp) {
        long long res = 1;
        base %= 1000000007;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % 1000000007;
            base = (base * base) % 1000000007;
            exp /= 2;
        }
        return res;
    }
public:
    int distanceSum(int m, int n, int k) {
        long long MOD = 1000000007;
        int total_cells = m * n;

        std::vector<long long> fact(total_cells + 1, 1);
        std::vector<long long> inv(total_cells + 1, 1);
        for (int i = 1; i <= total_cells; ++i) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        inv[total_cells] = power(fact[total_cells], MOD - 2);
        for (int i = total_cells - 1; i >= 0; --i) {
            inv[i] = (inv[i + 1] * (i + 1)) % MOD;
        }

        auto nCr = [&](int n_, int r_) -> long long {
            if (r_ < 0 || r_ > n_) return 0;
            return fact[n_] * inv[r_] % MOD * inv[n_ - r_] % MOD;
        };

        long long row_sum = ((1LL * m * (1LL * m * m - 1) / 6) % MOD) * ((1LL * n * n) % MOD) % MOD;
        long long col_sum = ((1LL * n * (1LL * n * n - 1) / 6) % MOD) * ((1LL * m * m) % MOD) % MOD;

        long long ways = nCr(total_cells - 2, k - 2);
        return (int)((row_sum + col_sum) % MOD * ways % MOD);
    }
};

class Solution {
    private static final long MOD = 1_000_000_007;

    private long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }

    public int distanceSum(int m, int n, int k) {
        int totalCells = m * n;
        long[] fact = new long[totalCells + 1];
        long[] inv = new long[totalCells + 1];
        fact[0] = 1;
        inv[0] = 1;
        for (int i = 1; i <= totalCells; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        inv[totalCells] = power(fact[totalCells], MOD - 2);
        for (int i = totalCells - 1; i >= 0; i--) {
            inv[i] = (inv[i + 1] * (i + 1)) % MOD;
        }

        long rowSum = ((1L * m * (1L * m * m - 1) / 6) % MOD) * ((1L * n * n) % MOD) % MOD;
        long colSum = ((1L * n * (1L * n * n - 1) / 6) % MOD) * ((1L * m * m) % MOD) % MOD;

        long ways = 0;
        if (k - 2 >= 0 && totalCells - 2 >= k - 2) {
            ways = fact[totalCells - 2] * inv[k - 2] % MOD * inv[totalCells - k] % MOD;
        }
        return (int)(((rowSum + colSum) % MOD * ways) % MOD);
    }
}

var distanceSum = function(m, n, k) {
    const MOD = 1000000007n;
    const totalCells = BigInt(m * n);
    const bm = BigInt(m);
    const bn = BigInt(n);
    const bk = BigInt(k);

    function power(base, exp) {
        let res = 1n;
        base = base % MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    const limit = Number(totalCells);
    const fact = new BigInt64Array(limit + 1);
    const inv = new BigInt64Array(limit + 1);
    fact[0] = 1n;
    inv[0] = 1n;
    for (let i = 1; i <= limit; i++) {
        fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    }
    inv[limit] = power(fact[limit], MOD - 2n);
    for (let i = limit - 1; i >= 0; i--) {
        inv[i] = (inv[i + 1] * BigInt(i + 1)) % MOD;
    }

    function nCr(n_, r_) {
        if (r_ < 0 || r_ > n_) return 0n;
        return (fact[n_] * inv[r_] % MOD * inv[n_ - r_]) % MOD;
    }

    const rowSum = ((bm * (bm * bm - 1n) / 6n) % MOD) * ((bn * bn) % MOD) % MOD;
    const colSum = ((bn * (bn * bn - 1n) / 6n) % MOD) * ((bm * bm) % MOD) % MOD;

    const ways = nCr(Number(totalCells - 2n), Number(bk - 2n));
    return Number(((rowSum + colSum) % MOD * ways) % MOD);
};
